SELECT
  'housing-germany-practical-guide',
  'housing-in-germany',
  'housing-and-living',
  'Germaniyada uy-joy topish: chet eldan turib va Germaniyaga kelgandan keyin',
  'Wohnungssuche in Deutschland: aus dem Ausland und nach der Ankunft',
  'Chet eldan turib yoki Germaniyaga kelgach uy qidirish: turar joy turlari, kontakt, hujjatlar, Besichtigung, Mietvertrag, Kaution, scam xavfi va Anmeldung bo‘yicha amaliy qo‘llanma.',
  'Praktischer Leitfaden zur Wohnungssuche aus dem Ausland oder nach der Ankunft: Wohnformen, Kontakt, Unterlagen, Besichtigung, Mietvertrag, Kaution, Betrugsschutz und Anmeldung.',
  'Uy qidirishda bitta universal yo‘l yo‘q. Eng tez natija uchun vaziyatingizga mos turar joy turini tanlang, bir nechta qidiruv kanalidan foydalaning, hujjatlarni tayyor tuting va pul yuborishdan oldin uy hamda shartnomani tekshiring.',
  'Bei der Wohnungssuche gibt es keinen einzigen richtigen Weg. Wählen Sie eine passende Wohnform, nutzen Sie mehrere Suchkanäle, halten Sie Unterlagen bereit und prüfen Sie Wohnung sowie Vertrag, bevor Sie Geld zahlen.',
  '9–11 daqiqa',
  '9–11 Minuten',
  '[{"label":"Yo‘l","value":"Chet eldan yoki Germaniyada turib"},{"label":"Muhim","value":"Anmeldung imkoniyatini oldindan tekshiring"},{"label":"Kaution","value":"Maksimal 3 oylik Kaltmiete"},{"label":"Scam","value":"Ko‘rmagan uy uchun Vorkasse qilmang"}]'::jsonb,
  '[{"label":"Start","value":"Aus dem Ausland oder vor Ort"},{"label":"Wichtig","value":"Anmeldemöglichkeit vorab klären"},{"label":"Kaution","value":"Höchstens 3 Monats-Kaltmieten"},{"label":"Betrug","value":"Keine Vorkasse für ungesehene Wohnungen"}]'::jsonb,
  '{"overview":{"title":"Vaziyatingizga mos yo‘l","paragraphs":["Chet eldan turib qidirsangiz online Besichtigung, vaqtinchalik Unterkunft, ish beruvchi/universitet yordami va Anmeldung imkoniyatini oldindan tekshirish muhim. Germaniyada bo‘lsangiz qidiruvni hujjatlar va Besichtigung bilan parallel olib boring."],"items":[]},"eligibility":{"title":"Turar joy va qidiruv kanallari","paragraphs":["Wohnung, WG, Zwischenmiete, möbliertes Apartment, Monteurzimmer, Studentenwohnheim, Gastfamilie yoki qisqa muddatli Unterkunft turli ehtiyojlarga mos. Anmeldung masalasi turar joy nomidan emas, konkret holat va Wohnungsgeberbestätigung imkoniyatidan kelib chiqadi."],"items":[]},"requirements":{"title":"Besichtigung va birinchi kontakt","paragraphs":["Birinchi xabarda ism, ish/o‘qish holati, kerak bo‘lsa daromad/finanslash holati, nechta odam ko‘chishi, qachondan uy kerakligi va Besichtigungga tayyorligingizni qisqa yozing.","Besichtigungda manzil, holat, xarajatlar, Mietvertragdagi tomonlar va Wohnungsgeberbestätigung masalasini aniqlashtiring."],"items":[]},"documents":{"title":"Bewerbungsmappe","paragraphs":["Vermieter talabiga qarab quyidagilarning bir qismi so‘ralishi mumkin; hammasi har bir holatda majburiy emas."],"items":["Personalausweis yoki Pass — faqat zarur hajmda va ishonchli qabul qiluvchiga.","Einkommensnachweis talab qilinishi mumkin.","Arbeitsvertrag yoki ishga kirish tasdig‘i talab qilinishi mumkin.","SCHUFA-Auskunft ayrim Vermieterlar tomonidan so‘raladi.","Mieterselbstauskunft so‘ralishi mumkin.","Bürgschaft, ayniqsa daromad hali yetarli bo‘lmasa, ayrim holatlarda so‘ralishi mumkin."]},"conditions":{"title":"Mietvertrag, xarajatlar va Anmeldung","paragraphs":["Kaltmiete — Betriebskostenlarsiz asosiy ijara. Nebenkosten — shartnomada ko‘rsatilgan qo‘shimcha Betriebskosten. Warmmiete odatda Kaltmiete va Nebenkosten yig‘indisi; Strom, Internet va ayrim isitish xarajatlari alohida bo‘lishi mumkin, shuning uchun shartnomani tekshiring.","BGB §551 bo‘yicha Wohnraum uchun Kaution maksimal uch oylik Betriebskostenlarsiz ijara miqdorida bo‘lishi mumkin. Pul kautionini uch teng oylik bo‘lib to‘lash huquqi mavjud.","BMG §17 bo‘yicha Wohnungga ko‘chib kirgan shaxs odatda ikki hafta ichida Anmeldung qiladi. BMG §19 bo‘yicha Wohnungsgeber ko‘chib kirishni tasdiqlaydi."],"items":[]},"warnings":{"title":"Uy-joy scam red flaglari","paragraphs":["Verbraucherzentrale fake Wohnunglarda pul va shaxsiy ma’lumotlarni olishga qaratilgan sxemalardan ogohlantiradi."],"items":["Bozor narxiga nisbatan g‘ayrioddiy arzon ‘ideal’ Wohnung.","Vermieter angeblich chet elda va Besichtigung qila olmaydi.","Besichtigung yoki Mietvertragdan oldin Kaution/Vorkasse talab qilinadi.","‘Kalitni pochta orqali yuboraman’ va buning uchun oldindan pul so‘raladi.","Airbnb, Booking yoki boshqa platformaga o‘xshatilgan tashqi fake payment/login sahifasi yuboriladi.","Shubhali email/domain yoki bosim bilan tez pul o‘tkazish talabi.","Pass/ID nusxasini nazoratsiz email yoki chat orqali yuborish talabi."]}}'::jsonb,
  '{"overview":{"title":"Den passenden Weg wählen","paragraphs":["Bei der Suche aus dem Ausland sind Online-Besichtigung, Übergangsunterkunft, Unterstützung durch Arbeitgeber/Hochschule und die vorherige Klärung der Anmeldemöglichkeit wichtig. Wer bereits in Deutschland ist, sollte Suche, Unterlagen und Besichtigungen parallel organisieren."],"items":[]},"eligibility":{"title":"Wohnformen und Suchkanäle","paragraphs":["Wohnung, WG, Zwischenmiete, möbliertes Apartment, Monteurzimmer, Studentenwohnheim, Gastfamilie oder kurzfristige Unterkunft passen zu unterschiedlichen Situationen. Ob eine Anmeldung möglich ist, folgt nicht pauschal aus der Wohnform, sondern aus dem konkreten Einzug und der Möglichkeit einer Wohnungsgeberbestätigung."],"items":[]},"requirements":{"title":"Besichtigung und erster Kontakt","paragraphs":["In die erste Nachricht gehören kurz Name, Arbeits-/Studienstatus, gegebenenfalls Einkommens- oder Finanzierungssituation, Anzahl der einziehenden Personen, gewünschter Einzugstermin und Bereitschaft zur Besichtigung.","Bei der Besichtigung Adresse, Zustand, Kosten, Vertragsparteien und die Wohnungsgeberbestätigung klären."],"items":[]},"documents":{"title":"Bewerbungsmappe","paragraphs":["Je nach Vermieter kann ein Teil der folgenden Unterlagen verlangt werden; nicht alles ist in jedem Fall verpflichtend."],"items":["Personalausweis oder Reisepass — nur im erforderlichen Umfang und an einen vertrauenswürdigen Empfänger.","Einkommensnachweise können verlangt werden.","Arbeitsvertrag oder Beschäftigungsnachweis kann verlangt werden.","Eine SCHUFA-Auskunft wird von manchen Vermietern verlangt.","Eine Mieterselbstauskunft kann verlangt werden.","Eine Bürgschaft kann insbesondere bei noch nicht ausreichendem Einkommen verlangt werden."]},"conditions":{"title":"Mietvertrag, Kosten und Anmeldung","paragraphs":["Kaltmiete ist die Grundmiete ohne ausgewiesene Betriebskosten. Nebenkosten sind die im Vertrag vereinbarten Betriebskosten. Warmmiete bezeichnet typischerweise Kaltmiete plus Nebenkosten; Strom, Internet und einzelne Heizkosten können separat anfallen — maßgeblich ist der Vertrag.","Nach § 551 BGB darf eine Mietsicherheit bei Wohnraum höchstens drei Monatsmieten ohne ausgewiesene Betriebskosten betragen. Eine Geldkaution darf in drei gleichen Monatsraten gezahlt werden.","Nach § 17 BMG ist eine bezogene Wohnung grundsätzlich innerhalb von zwei Wochen anzumelden. Nach § 19 BMG wirkt der Wohnungsgeber durch die Bestätigung des Einzugs mit."],"items":[]},"warnings":{"title":"Warnzeichen für Wohnungsbetrug","paragraphs":["Die Verbraucherzentrale warnt bei Fake-Wohnungen vor Maschen, die auf Vorauszahlungen oder persönliche Daten zielen."],"items":["Ungewöhnlich günstige ‘Traumwohnung’ im Vergleich zum örtlichen Markt.","Der angebliche Vermieter ist im Ausland und eine Besichtigung sei nicht möglich.","Kaution oder Vorkasse wird vor Besichtigung oder Vertrag verlangt.","Der Schlüssel soll gegen Vorauszahlung per Post geschickt werden.","Externe Fake-Zahlungs- oder Login-Seiten im Stil von Airbnb, Booking oder anderen Plattformen.","Auffällige E-Mail-Adresse/Domain oder Druck, sofort Geld zu überweisen.","Unkontrollierte Übersendung von Pass- oder Ausweiskopien per E-Mail oder Chat."]}}'::jsonb,
  '[{"title":"Qidirish","description":"Bir nechta kanalni parallel ishlating va budget, joy, muddat bo‘yicha filterlang."},{"title":"Kontakt","description":"Qisqa, shaxsiy va kerakli ma’lumotlar bilan murojaat qiling."},{"title":"Hujjatlar","description":"Vermieter so‘rashi mumkin bo‘lgan hujjatlarni xavfsiz tayyorlang."},{"title":"Besichtigung","description":"Uy, manzil, xarajat va Anbieter/Vermieterni tekshiring."},{"title":"Zusage","description":"Og‘zaki va’da o‘rniga shartnoma shartlarini yozma ko‘ring."},{"title":"Mietvertrag","description":"Ijara, Nebenkosten, muddat va tomonlarni tekshirib imzolang."},{"title":"Kaution","description":"Qonuniy limit va to‘lov vaqtini tekshiring; shoshilinch Vorkassedan saqlaning."},{"title":"Kalit","description":"Kalitni real topshirish va Wohnung holatini hujjatlashtirish ma’qul."},{"title":"Wohnungsgeberbestätigung","description":"Anmeldung uchun Wohnungsgeberdan ko‘chib kirish tasdig‘ini oling."},{"title":"Anmeldung","description":"Haqiqiy ko‘chib kirgandan keyin odatda ikki hafta ichida Meldebehördeda ro‘yxatdan o‘ting."}]'::jsonb,
  '[{"title":"Suchen","description":"Mehrere Kanäle parallel nutzen und nach Budget, Ort und Dauer filtern."},{"title":"Kontakt","description":"Kurz, persönlich und mit den relevanten Angaben anfragen."},{"title":"Unterlagen","description":"Mögliche Vermieter-Unterlagen sicher vorbereiten."},{"title":"Besichtigung","description":"Wohnung, Adresse, Kosten und Anbieter/Vermieter prüfen."},{"title":"Zusage","description":"Nicht nur auf mündliche Zusagen vertrauen, sondern Vertragsbedingungen schriftlich prüfen."},{"title":"Mietvertrag","description":"Miete, Nebenkosten, Laufzeit und Vertragsparteien vor der Unterschrift prüfen."},{"title":"Kaution","description":"Gesetzliche Grenze und Fälligkeit beachten; keine übereilte Vorkasse."},{"title":"Schlüssel","description":"Schlüssel real übernehmen und den Wohnungszustand dokumentieren."},{"title":"Wohnungsgeberbestätigung","description":"Vom Wohnungsgeber die Bestätigung des Einzugs für die Anmeldung erhalten."},{"title":"Anmeldung","description":"Nach dem tatsächlichen Einzug grundsätzlich innerhalb von zwei Wochen bei der Meldebehörde anmelden."}]'::jsonb,
  '[]'::jsonb,
  '[]'::jsonb,
  '[{"title":"§ 551 BGB – Begrenzung und Anlage von Mietsicherheiten","organization":"Bundesministerium der Justiz / Bundesamt für Justiz","url":"https://www.gesetze-im-internet.de/bgb/__551.html","language":"de"},{"title":"§ 17 BMG – Anmeldung, Abmeldung","organization":"Bundesministerium der Justiz / Bundesamt für Justiz","url":"https://www.gesetze-im-internet.de/bmg/__17.html","language":"de"},{"title":"§ 19 BMG – Mitwirkung des Wohnungsgebers","organization":"Bundesministerium der Justiz / Bundesamt für Justiz","url":"https://www.gesetze-im-internet.de/bmg/__19.html","language":"de"},{"title":"Fake-Wohnungen im Internet: So erkennen Sie falsche Immobilienanzeigen","organization":"Verbraucherzentrale","url":"https://www.verbraucherzentrale.de/wissen/vertraege-reklamation/abzocke/fakewohnungen-im-internet-so-erkennen-sie-falsche-immobilienanzeigen-27576","language":"de"},{"title":"Studierendenwohnheime","organization":"Deutsches Studierendenwerk","url":"https://www.studierendenwerke.de/themen/wohnen/studierendenwohnheime","language":"de"},{"title":"Au-pair","organization":"Bundesagentur für Arbeit","url":"https://www.arbeitsagentur.de/unternehmen/arbeitskraefte/au-pair","language":"de"}]'::jsonb,
  ARRAY[]::text[],
  '2026-09-24',
  'published',
  TRUE
WHERE NOT EXISTS (
  SELECT 1 FROM guide_articles WHERE slug = 'housing-in-germany'
